from app.database import db

class Note(db.Model):
    __tablename__ = 'notes'

    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(255), nullable=False)
    content = db.Column(db.Text, nullable=False)
    created_at = db.Column(db.DateTime, default=db.func.current_timestamp())

    def __init__(self, title, content):
        self.title = title
        self.content = content

    def save(self):
        """
        Save the current note instance to the database.
        """
        db.session.add(self)
        db.session.commit()

    def delete(self):
        """
        Delete the current note instance from the database.
        """
        db.session.delete(self)
        db.session.commit()

    @staticmethod
    def get_all_notes():
        """
        Retrieve all notes from the database.
        """
        return Note.query.all()

    @staticmethod
    def get_note_by_id(note_id):
        """
        Retrieve a single note by its ID.
        """
        return Note.query.get(note_id)

    @staticmethod
    def search_notes(query):
        """
        Search notes by title or content that contains the query string.
        """
        return Note.query.filter(
            db.or_(
                Note.title.ilike(f'%{query}%'),
                Note.content.ilike(f'%{query}%')
            )
        ).all()

{% extends "base.html" %}

{% block title %}
    Search Notes
{% endblock %}

{% block content %}
    <div class="search-container">
        <h1>Search Notes</h1>
        <form action="{{ url_for('notes_bp.search_notes') }}" method="get">
            <input type="text" name="q" placeholder="Search notes..." required>
            <button type="submit">Search</button>
        </form>
    </div>

    {% if notes %}
        <div class="notes-list">
            <h2>Search Results:</h2>
            <ul>
                {% for note in notes %}
                    <li>
                        <a href="{{ url_for('notes_bp.get_note', note_id=note.id) }}">
                            {{ note.title }}
                        </a>
                        <p>{{ note.content[:100] }}...</p>
                    </li>
                {% endfor %}
            </ul>
        </div>
    {% elif request.args.get('q') %}
        <p>No notes found for your search query.</p>
    {% endif %}
{% endblock %}

/* Path: static/css/styles.css */
/* Purpose: CSS file for styling the application */

/* General styling for the application */
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    background-color: #f8f9fa;
    color: #343a40;
}

header {
    background-color: #007bff;
    color: white;
    padding: 1rem;
    text-align: center;
}

header h1 {
    margin: 0;
    font-size: 2rem;
}

main {
    padding: 2rem;
}

footer {
    background-color: #343a40;
    color: white;
    text-align: center;
    padding: 1rem;
    position: fixed;
    bottom: 0;
    width: 100%;
}

/* Styling for forms */
form {
    max-width: 600px;
    margin: 0 auto;
    background: white;
    padding: 1.5rem;
    border-radius: 8px;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

form input[type="text"],
